def test_search_tasks_sql_injection(monkeypatch):
    import sqlite3
    # Mock connection and cursor to capture executed query
    executed = {}
    class MockCursor:
        def execute(self, q, params=None):
            executed['query'] = q
            executed['params'] = params
            return self
        def fetchall(self):
            return []
    class MockConn:
        def __enter__(self): return self
        def __exit__(self, exc_type, exc, tb): pass
        def execute(self, q, params=None):
            executed['query'] = q
            executed['params'] = params
            return MockCursor()
        def close(self): pass
    def mock_connect(db):
        return MockConn()
    monkeypatch.setattr(sqlite3, 'connect', mock_connect)
    from app.db import search_tasks
    search_tasks("test' OR 1=1 --")
    assert executed['params'] is None
    assert "'test' OR 1=1 --'" not in executed['query']

def test_search_tasks_return_type(monkeypatch):
    import sqlite3
    class MockConn:
        def execute(self, q, params=None):
            class MockCursor:
                def fetchall(self):
                    return [(1, 'Task 1')]
            return MockCursor()
        def close(self): pass
    monkeypatch.setattr(sqlite3, 'connect', lambda _: MockConn())
    from app.db import search_tasks
    result = search_tasks('foo')
    assert isinstance(result, list)
    assert all(isinstance(row, dict) for row in result), "Rows should be dicts"

